import{_ as n,o as s,c as e,a2 as t}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"工程交付与仓库结构","description":"Hearth 的工程原则、技术栈、仓库布局、进程模型、数据目录、CLI、测试、可观测性与发布迁移。","frontmatter":{"title":"工程交付与仓库结构","description":"Hearth 的工程原则、技术栈、仓库布局、进程模型、数据目录、CLI、测试、可观测性与发布迁移。","outline":[2,3]},"headers":[],"relativePath":"delivery/engineering.md","filePath":"delivery/engineering.md","lastUpdated":1793706118000}'),l={name:"delivery/engineering.md"};function p(i,a,r,o,d,c){return s(),e("div",null,[...a[0]||(a[0]=[t(`<p class="eyebrow">ENGINEERING</p><h1 id="工程交付与仓库结构" tabindex="-1">工程交付与仓库结构 <a class="header-anchor" href="#工程交付与仓库结构" aria-label="Permalink to &quot;工程交付与仓库结构&quot;">​</a></h1><p class="lead">工程原则、推荐技术栈、仓库布局、进程模型、数据目录、CLI、Event Log、测试、可观测性与发布迁移。</p><h2 id="工程架构与仓库结构" tabindex="-1">工程架构与仓库结构 <a class="header-anchor" href="#工程架构与仓库结构" aria-label="Permalink to &quot;工程架构与仓库结构&quot;">​</a></h2><h3 id="工程原则" tabindex="-1">工程原则 <a class="header-anchor" href="#工程原则" aria-label="Permalink to &quot;工程原则&quot;">​</a></h3><ul><li><strong>模块化单体优先</strong>：早期不引入微服务；</li><li><strong>纵向切片优先</strong>：每个里程碑都必须同时包含 UI、持久状态、执行、验证和恢复；</li><li><strong>界面即验收面</strong>：用户不能在浏览器中完成的能力，不进入阶段出口；</li><li><strong>单写者</strong>：同一 State Root 只有一个写权威；</li><li><strong>事件溯源</strong>：事实写 Event Log，UI/索引是投影；</li><li><strong>Schema 优先</strong>：输入、输出、Effect、Approval 都有版本化 schema；</li><li><strong>适配器隔离</strong>：Codex、Connector、Browser、GUI、Sandbox 都通过接口接入；</li><li><strong>本地优先</strong>：默认数据本地，云资源可替换；</li><li><strong>可回滚</strong>：数据库、技能、配置和发布都有回滚路径；</li><li><strong>可观测</strong>：每个任务有 correlation id、trace 和成本归因。</li></ul><h3 id="推荐技术栈" tabindex="-1">推荐技术栈 <a class="header-anchor" href="#推荐技术栈" aria-label="Permalink to &quot;推荐技术栈&quot;">​</a></h3><p>以下为默认建议，不是不可替换的宗教：</p><table tabindex="0"><thead><tr><th>层</th><th>建议</th></tr></thead><tbody><tr><td>语言</td><td>TypeScript / Node.js 22+</td></tr><tr><td>包管理</td><td>pnpm</td></tr><tr><td>单体仓库</td><td>Turborepo 或等价工具</td></tr><tr><td>常驻服务</td><td>Node + Fastify/Hono</td></tr><tr><td>数据库</td><td>SQLite WAL + migration</td></tr><tr><td>Schema</td><td>Zod / JSON Schema</td></tr><tr><td>Web</td><td>React + Vite + PWA</td></tr><tr><td>实时更新</td><td>SSE 优先，必要时 WebSocket</td></tr><tr><td>浏览器</td><td>Playwright</td></tr><tr><td>文档/数据</td><td>Python sidecar + 成熟解析库</td></tr><tr><td>沙箱</td><td>Docker 起步，微虚拟机用于不受信任任务</td></tr><tr><td>可观测</td><td>OpenTelemetry + 本地日志/指标</td></tr><tr><td>测试</td><td>Vitest/Playwright/契约测试/故障注入</td></tr><tr><td>打包</td><td>npm CLI + Docker Compose</td></tr></tbody></table><p>选择 TypeScript 的理由是前后端共享类型、事件协议和 schema，适合快速构建本地 Web 与 CLI；文档/数据密集处理通过 Python sidecar 补足生态，不把整个系统拆成多语言微服务。</p><h3 id="仓库布局" tabindex="-1">仓库布局 <a class="header-anchor" href="#仓库布局" aria-label="Permalink to &quot;仓库布局&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearth-os/</span></span>
<span class="line"><span>  apps/</span></span>
<span class="line"><span>    hearthd/              # 常驻服务：Gateway / Control / Harness</span></span>
<span class="line"><span>    web/                  # 任务卡、审批、产物、PWA</span></span>
<span class="line"><span>    cli/                  # hearth 命令</span></span>
<span class="line"><span>    agentd/               # 设备节点（后续）</span></span>
<span class="line"><span>  packages/</span></span>
<span class="line"><span>    core/                 # 领域模型、状态机、错误分类</span></span>
<span class="line"><span>    eventlog/             # Event Log、投影、migration</span></span>
<span class="line"><span>    harness/              # Ticket、Run、lease、outbox、恢复</span></span>
<span class="line"><span>    policy/               # Policy、Mandate、Capability、风险</span></span>
<span class="line"><span>    context/              # Context Compiler、Task Pack</span></span>
<span class="line"><span>    token/                # Token Governor、预算、归因</span></span>
<span class="line"><span>    memory/               # 记忆写入、检索、遗忘、同步</span></span>
<span class="line"><span>    evolution/            # 轨迹、技能、评估、晋升、回滚</span></span>
<span class="line"><span>    executors/</span></span>
<span class="line"><span>      native/</span></span>
<span class="line"><span>      codex/</span></span>
<span class="line"><span>      connector/</span></span>
<span class="line"><span>      browser/</span></span>
<span class="line"><span>      gui/</span></span>
<span class="line"><span>      document/</span></span>
<span class="line"><span>    connectors/           # email/calendar/docs/im/issue</span></span>
<span class="line"><span>    gateway/              # 渠道、设备、通知、身份</span></span>
<span class="line"><span>    execution/            # Sandbox Provider、egress、Broker</span></span>
<span class="line"><span>    artifacts/            # 产物、哈希、版本、验证</span></span>
<span class="line"><span>    evals/                # 任务集、runner、scorer</span></span>
<span class="line"><span>    shared/               # schema、类型、工具</span></span>
<span class="line"><span>  sidecars/</span></span>
<span class="line"><span>    docdata/              # Python 文档/数据管道</span></span>
<span class="line"><span>  fixtures/</span></span>
<span class="line"><span>  docs/</span></span>
<span class="line"><span>    adr/</span></span>
<span class="line"><span>    architecture/</span></span>
<span class="line"><span>  docker/</span></span></code></pre></div><h3 id="进程模型" tabindex="-1">进程模型 <a class="header-anchor" href="#进程模型" aria-label="Permalink to &quot;进程模型&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearth CLI / Web / Mobile</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>       hearthd</span></span>
<span class="line"><span>  ├─ Gateway</span></span>
<span class="line"><span>  ├─ Control Plane</span></span>
<span class="line"><span>  ├─ Durable Harness</span></span>
<span class="line"><span>  ├─ Token Governor / Context Compiler</span></span>
<span class="line"><span>  ├─ Executor Supervisor</span></span>
<span class="line"><span>  ├─ Event Log / projections</span></span>
<span class="line"><span>  ├─ Sandbox Provider client</span></span>
<span class="line"><span>  ├─ Credential Broker</span></span>
<span class="line"><span>  └─ Effect Dispatcher</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ├─ Codex adapter</span></span>
<span class="line"><span>          ├─ Browser worker</span></span>
<span class="line"><span>          ├─ Connector workers</span></span>
<span class="line"><span>          ├─ Document/Data sidecar</span></span>
<span class="line"><span>          └─ Device agentd（后续）</span></span></code></pre></div><p>所有执行器通过统一协议连接，不直接写主数据库。SQLite 由 <code>hearthd</code> 单进程写入；执行器通过 RPC/任务队列得到工作。</p><h3 id="数据目录" tabindex="-1">数据目录 <a class="header-anchor" href="#数据目录" aria-label="Permalink to &quot;数据目录&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.hearth/</span></span>
<span class="line"><span>  state.db                # Event Log + projections</span></span>
<span class="line"><span>  artifacts/              # 内容寻址产物</span></span>
<span class="line"><span>  workspaces/             # 临时和项目工作区</span></span>
<span class="line"><span>  config/</span></span>
<span class="line"><span>    policy.yaml</span></span>
<span class="line"><span>    connections.yaml</span></span>
<span class="line"><span>  secrets/                # 加密凭据或 Broker 指针</span></span>
<span class="line"><span>  logs/</span></span>
<span class="line"><span>  backups/</span></span>
<span class="line"><span>  devices/</span></span></code></pre></div><p>敏感目录权限最小化；备份加密；设备同步只传输必要的投影和产物引用。</p><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearth init</span></span>
<span class="line"><span>hearth run &quot;整理这周的竞品更新并生成周报草稿&quot;</span></span>
<span class="line"><span>hearth status</span></span>
<span class="line"><span>hearth inbox</span></span>
<span class="line"><span>hearth approve &lt;id&gt;</span></span>
<span class="line"><span>hearth artifacts</span></span>
<span class="line"><span>hearth memory search &quot;项目 A 的决策&quot;</span></span>
<span class="line"><span>hearth memory forget &lt;id&gt;</span></span>
<span class="line"><span>hearth doctor</span></span>
<span class="line"><span>hearth export</span></span></code></pre></div><p>CLI 输出支持人类可读和 JSON 两种模式，方便脚本和自动化测试。</p><h3 id="event-log-与投影" tabindex="-1">Event Log 与投影 <a class="header-anchor" href="#event-log-与投影" aria-label="Permalink to &quot;Event Log 与投影&quot;">​</a></h3><ul><li>Event 只追加，不原地更新；</li><li>每个 Event 有 schemaVersion、correlationId、causationId；</li><li>任务状态、收件箱、产物和成本都是投影；</li><li>投影可重建；</li><li>事件 hash 链或等价完整性校验；</li><li>大内容存 Artifact，Event 只存引用；</li><li>migration 必须兼容旧事件；</li><li>事件重放不能产生外部副作用。</li></ul><h3 id="任务与-lease" tabindex="-1">任务与 lease <a class="header-anchor" href="#任务与-lease" aria-label="Permalink to &quot;任务与 lease&quot;">​</a></h3><ul><li>每个 Ticket 同一时刻最多一个有效 Assignment；</li><li>lease 带 fencing token；</li><li>执行器写入前校验 fencing token；</li><li>设备离线后 lease 过期，任务可重新分配；</li><li>重新分配不能重复外部 Effect；</li><li>任务状态迁移有显式事件和条件；</li><li>子任务继承父任务预算和权限交集。</li></ul><h3 id="测试策略" tabindex="-1">测试策略 <a class="header-anchor" href="#测试策略" aria-label="Permalink to &quot;测试策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>内容</th></tr></thead><tbody><tr><td>Unit</td><td>schema、策略、验证器、成本计算</td></tr><tr><td>Contract</td><td>Executor、Connector、Sandbox、Broker</td></tr><tr><td>Integration</td><td>Event Log、outbox、lease、恢复</td></tr><tr><td>E2E</td><td>任务卡、审批、产物、邮件草稿</td></tr><tr><td>Slice E2E</td><td>每个增量从创建任务到产物/恢复的浏览器路径</td></tr><tr><td>Fault Injection</td><td>崩溃、断网、超时、重复、磁盘满</td></tr><tr><td>Replay</td><td>历史轨迹重放、换路由</td></tr><tr><td>Security</td><td>注入、越权、秘密、沙箱、egress</td></tr><tr><td>Performance</td><td>启动、查询、长任务、并发上限</td></tr></tbody></table><h3 id="可观测性" tabindex="-1">可观测性 <a class="header-anchor" href="#可观测性" aria-label="Permalink to &quot;可观测性&quot;">​</a></h3><ul><li>每个 Task/Run 有 trace id；</li><li>每次模型调用记录模型、Token、成本和延迟；</li><li>每次工具调用记录参数哈希、结果状态和资源；</li><li>每次外部副作用记录幂等键与 Receipt；</li><li>UI 只展示用户需要的事件；</li><li>详细信息保留在本地审计视图；</li><li>日志自动脱敏；</li><li>指标用于路由和评估，不用于操纵用户。</li></ul><h3 id="发布与迁移" tabindex="-1">发布与迁移 <a class="header-anchor" href="#发布与迁移" aria-label="Permalink to &quot;发布与迁移&quot;">​</a></h3><ul><li>版本化 schema 和 API；</li><li>数据库 migration 向前兼容；</li><li>执行器版本锁定；</li><li>技能版本化；</li><li>发布前跑评测和故障注入；</li><li>支持回滚到上一个稳定版本；</li><li>升级不破坏历史事件和产物；</li><li>用户可导出和迁移。</li><li>每个增量保留可回退版本，不允许只能靠重新搭建环境恢复。</li></ul><hr>`,32)])])}const g=n(l,[["render",p]]);export{u as __pageData,g as default};
